function bounceBricks(state) {
  const { ball } = state;
  const overlapped = [];
  for (const brick of state.bricks) {
    if (brick.alive && collides(ball, brick)) overlapped.push(brick);
  }
  if (overlapped.length === 0) return;

  // Union of every overlapped brick: a seam hit touches 2 (even 4) bricks at
  // once, and resolving them separately would flip the same axis twice and
  // cancel the bounce (ghost collision). One union = one contact = one normal.
  const u = {
    x: Math.min(...overlapped.map((b) => b.x)),
    y: Math.min(...overlapped.map((b) => b.y)),
    x2: Math.max(...overlapped.map((b) => b.x + b.w)),
    y2: Math.max(...overlapped.map((b) => b.y + b.h)),
  };

  const dx = Math.min(ball.x + ball.r - u.x, u.x2 - (ball.x - ball.r));
  const dy = Math.min(ball.y + ball.r - u.y, u.y2 - (ball.y - ball.r));

  if (dx < dy) {
    ball.vx = -ball.vx;
    const leftOverlap = ball.x + ball.r - u.x;
    ball.x = leftOverlap < u.x2 - (ball.x - ball.r) ? u.x - ball.r : u.x2 + ball.r;
  } else if (dy < dx) {
    ball.vy = -ball.vy;
    const topOverlap = ball.y + ball.r - u.y;
    ball.y = topOverlap < u.y2 - (ball.y - ball.r) ? u.y - ball.r : u.y2 + ball.r;
  } else {
    // Corner: equal penetration on both axes — flip both and push out to the
    // nearest corner (D4b).
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    const left = ball.x < u.x + (u.x2 - u.x) / 2;
    const top = ball.y < u.y + (u.y2 - u.y) / 2;
    ball.x = left ? u.x - ball.r : u.x2 + ball.r;
    ball.y = top ? u.y - ball.r : u.y2 + ball.r;
  }

  for (const brick of overlapped) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }
}
```

