// Bounces the ball off the live bricks it overlaps, destroys them and scores.
//
// Resolution rule: the axis of the bounce is the axis of smallest penetration
// (side face -> flip vx, top/bottom face -> flip vy), and the ball is pushed
// back out of the brick so it never stays inside (no sticky overlap). A brick
// dies exactly once, on the pass that touches it.
function bounceBricks(state) {
  const { ball } = state;
  for (const brick of state.bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;

    // Penetration depths of the ball box against the brick, per axis.
    const dx = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
    const dy = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

    if (dx < dy) {
      // Side hit: flip vx, push out along x toward the entered side.
      ball.vx = -ball.vx;
      const leftOverlap = ball.x + ball.r - brick.x;
      ball.x = leftOverlap < brick.x + brick.w - (ball.x - ball.r) ? brick.x - ball.r : brick.x + brick.w + ball.r;
    } else {
      // Top/bottom hit: flip vy, push out along y toward the entered side.
      ball.vy = -ball.vy;
      const topOverlap = ball.y + ball.r - brick.y;
      ball.y = topOverlap < brick.y + brick.h - (ball.y - ball.r) ? brick.y - ball.r : brick.y + brick.h + ball.r;
    }

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }
}

