export function step(state, dt) {
  const { ball, paddle } = state;

  // Substep the movement so no brick can be fully crossed between two
  // samples: each substep displaces the ball by at most 2*BALL_R (= 14px),
  // which is strictly less than BRICK_H + 2*BALL_R = 34. A fast ball can
  // therefore never tunnel through a brick (see D5).
  const speed = Math.hypot(ball.vx, ball.vy);
  const subDt = speed > 0 ? Math.min(dt, MAX_STEP / speed) : dt;

  let remaining = dt;
  while (remaining > 0 && ball.y - ball.r <= HEIGHT) {
    const sub = Math.min(subDt, remaining);
    ball.x += ball.vx * sub;
    ball.y += ball.vy * sub;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }

    // Bricks
    bounceBricks(state);

    remaining -= sub;
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}
