content.text:
// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  advanceLevel,
  ballSpeed,
  comboMultiplier,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// --- Brick collision defects (playtest, see .scratch/to_fix.md) ------------

// D1: a head-on hit on the bottom face of a brick must bounce the ball down.
test('D1: head-on bottom-face hit bounces the ball down', () => {
  const state = createState(1);
  // Row-0 brick [4,76]x[48,68] (col 0). Ball 1px inside it, moving up.
  state.ball = { x: 40, y: 74, r: 7, vx: 0, vy: -260 };
  step(state, 0.05);
  assert.ok(state.ball.vy > 0, 'vy must flip DOWN after hitting the bottom face');
});

// D2: the bounce must push the ball out of the brick (no sticky overlap).
test('D2: after the bounce the ball no longer overlaps the brick', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 0 && b.x === 4);
  state.ball = { x: 40, y: 74, r: 7, vx: 0, vy: -260 };
  step(state, 0.05);
  assert.ok(state.ball.vy > 0, 'bounce happened');
  assert.ok(!collides(state.ball, brick), 'ball must be pushed out of the brick');
});

// D3: the seam between two bricks must not double-flip vy (ghost collision).
test('D3: one vy flip when the ball straddles a column seam', () => {
  const state = createState(1);
  // Row-1 bricks [4,76]x[76,96] and [84,156]x[76,96]. The 8px seam at
  // x=76..84 is narrower than the ball (14px): the ball at x=80 spans both.
  const seam = state.bricks.filter((b) => b.row === 1 && (b.x === 4 || b.x === 84));
  state.ball = { x: 80, y: 104, r: 7, vx: 0, vy: -260 }; // below the seam, moving up
  step(state, 0.05);
  assert.ok(state.ball.vy > 0, 'vy must flip exactly once: the ball bounces DOWN off the seam');
  assert.ok(seam.every((b) => !b.alive), 'both seam bricks die');
  assert.ok(state.ball.y >= 96 + 7, 'ball pushed below the seam row');
});

// D4a: a side-face hit flips vx and leaves vy untouched.
test('D4a: side-face hit flips vx and leaves vy untouched', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 2 && b.x === 84); // [84,156]x[104,124]
  state.ball = { x: 85, y: 114, r: 7, vx: 260, vy: 50 }; // inside x-range, left face
  step(state, 0.005);
  assert.ok(state.ball.vx < 0, 'vx must flip LEFT on a side hit');
  assert.equal(state.ball.vy, 50, 'vy must be untouched by a side hit');
  assert.ok(!brick.alive, 'brick destroyed');
  assert.ok(!collides(state.ball, brick), 'ball pushed out');
});

// D4b: a corner hit (equal penetration on both axes) flips both velocities.
test('D4b: corner hit flips both velocities', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 2 && b.x === 84); // [84,156]x[104,124]
  // Ball at (83,125), moving up-right: the 0.03s step lands the sample on the
  // bottom-left corner with dx == dy == 13.8.
  state.ball = { x: 83, y: 125, r: 7, vx: 260, vy: -260 };
  step(state, 0.03);
  assert.ok(state.ball.vx < 0, 'vx flipped on a corner hit');
  assert.ok(state.ball.vy > 0, 'vy flipped on a corner hit');
  assert.ok(!brick.alive, 'brick destroyed');
  assert.ok(!collides(state.ball, brick), 'ball pushed out');
});

// D5: a 50ms step longer than the brick must not tunnel through it.
test('D5: a step longer than the brick does not tunnel through it', () => {
  const state = createState(6); // ballSpeed(6) = 710
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 4); // [4,76]x[160,180]
  // One 50ms step at 710 px/s covers 35.5px > BRICK_H + 2r = 34.
  state.ball = { x: 40, y: 187, r: 7, vx: 0, vy: -ballSpeed(6) };
  step(state, 0.05);
  assert.ok(state.ball.vy > 0, 'must bounce off the brick even though the step crosses it');
  assert.ok(!brick.alive, 'brick destroyed');
});

// D6: a fast ball must never fall through the paddle (swept test: the ball's
// bottom edge crossed paddle.y during the step).
test('D6: the ball never falls through the paddle', () => {
  const state = createState(2); // ballSpeed(2) = 350
  // 1px above the paddle top; one 50ms step covers 17.5px > paddle.h + 2r = 26
  // is not even needed: 17.5px already skips the 12px detection band.
  state.ball = { x: 320, y: 440, r: 7, vx: 0, vy: 350 };
  const lost = step(state, 0.05);
  assert.equal(lost, false);
  assert.ok(state.ball.vy < 0, 'must bounce up off the paddle');
});

// D7: a hit on the exact paddle center must not zero vx (dead zone).
test('D7: a center hit keeps a playable horizontal speed', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 440, r: 7, vx: 50, vy: 300 }; // exact center: hit = 0
  step(state, 0.02);
  assert.ok(state.ball.vy < 0, 'bounced');
  assert.ok(
    Math.abs(state.ball.vx) >= 0.1 * ballSpeed(1),
    `|vx| = ${state.ball.vx} must stay >= ${0.1 * ballSpeed(1)}`
  );
});

// D8: the paddle bounce must conserve the level speed.
test('D8: the paddle bounce conserves the level speed', () => {
  const state = createState(1);
  state.ball = { x: 360, y: 440, r: 7, vx: 100, vy: 300 }; // hit ~ +0.875 (right half)
  step(state, 0.02);
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(
    Math.abs(norm - ballSpeed(1)) < 1e-6,
    `norm ${norm} must equal ballSpeed(1) = ${ballSpeed(1)}`
  );
});

// D9: the combo multiplier must be bounded (score cannot blow up).
test('D9: combo multiplier is bounded', () => {
  assert.equal(comboMultiplier(9), 5, 'combo 9 must be clamped to x5');
  assert.equal(comboMultiplier(100), 5, 'combo 100 must be clamped to x5');
});

// D10: advancing a level relaunches the ball, so the combo (tied to the
// current rally) must reset.
test('D10: advancing a level resets the combo', () => {
  const state = createState(1);
  state.bricks.forEach((b) => {
    b.alive = false;
  });
  state.combo = 7;
  advanceLevel(state);
  assert.equal(state.combo, 0, 'combo must reset on level up');
  assert.equal(state.level, 2);
  assert.ok(state.bricks.every((b) => b.alive), 'fresh brick grid');
});

// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.

